static class Dates
{
    static readonly int Epoch = new DateOnly(2000, 1, 1).DayNumber;
    public static bool Leap(int year) => DateTime.IsLeapYear(year);
    public static int MonthLength(int year, int month) => DateTime.DaysInMonth(year, month);
    public static int DayNumber(int year, int month, int day) => new DateOnly(year, month, day).DayNumber - Epoch;
    public static DateOnly Civil(int day) => DateOnly.FromDayNumber(day + Epoch);
    public static bool Valid(string text) => DateOnly.TryParseExact(text, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out DateOnly date) && date.Year is >= 2001 and <= 2099;
    public static int Parse(string text) => DateOnly.ParseExact(text, "yyyy-MM-dd", CultureInfo.InvariantCulture).DayNumber - Epoch;
    public static string Format(int day) => Civil(day).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
}
sealed class Calendar
{
    public HashSet<int> Holidays = [];
    public bool Business(int day) => (day + 5) % 7 < 5 && !Holidays.Contains(day);
    public int Move(int day, int count)
    {
        int step = count < 0 ? -1 : 1; if (count < 0) count = -count;
        while (count > 0) { day += step; if (Business(day)) count--; }
        return day;
    }
    public int Adjust(int day, string rule)
    {
        if (rule == "UNADJUSTED") return day;
        int following = day; while (!Business(following)) following++;
        if (rule == "FOLLOWING" || rule == "MODIFIED_FOLLOWING" && Dates.Civil(following).Month == Dates.Civil(day).Month) return following;
        while (!Business(day)) day--; return day;
    }
}
readonly record struct Fraction(long Numerator, long Denominator)
{
    public double Value => (double)Numerator / Denominator;
}
static class Daycount
{
    public static Fraction Between(string convention, int start, int end)
    {
        DateOnly first = Dates.Civil(start), last = Dates.Civil(end); int d1 = first.Day, d2 = last.Day;
        if (convention == "30E/360") { d1 = Math.Min(d1, 30); d2 = Math.Min(d2, 30); }
        else
        {
            bool february = first.Month == 2 && d1 == Dates.MonthLength(first.Year, first.Month);
            if (february && last.Month == 2 && d2 == Dates.MonthLength(last.Year, last.Month)) d2 = 30;
            if (february) d1 = 30;
            if (d2 == 31 && d1 >= 30) d2 = 30;
            if (d1 == 31) d1 = 30;
        }
        return new(360 * (last.Year - first.Year) + 30 * (last.Month - first.Month) + d2 - d1, 360);
    }
}
static class Bisection
{
    public static double Solve(Func<double, double> function, double low, double high, double target)
    {
        for (int i = 0; i < 80; i++) { double middle = (low + high) / 2; if (function(middle) > target) low = middle; else high = middle; }
        return (low + high) / 2;
    }
}
readonly record struct Risk(double Macaulay, double Modified, double Convexity, double Dv01);
sealed class YieldPricer(List<double> flows, double fraction, int frequency, long outstanding)
{
    List<double> Values(double rate)
    {
        double first = 1 + fraction * rate / frequency, growth = 1 + rate / frequency, factor = 1;
        List<double> values = []; foreach (double cash in flows) { values.Add(cash / (first * factor)); factor *= growth; } return values;
    }
    public double Dirty(double rate) { double total = 0; foreach (double value in Values(rate)) total += value; return total * 100 / outstanding; }
    public double Solve(double target) => Bisection.Solve(Dirty, 0, 1, target);
    public Risk Measure(double rate)
    {
        List<double> present = Values(rate); double growth = 1 + rate / frequency, total = 0, weighted = 0, curvature = 0;
        for (int i = 0; i < present.Count; i++) { double years = (i + fraction) / frequency; total += present[i]; weighted += years * present[i]; curvature += years * (years + 1.0 / frequency) * present[i]; }
        double macaulay = weighted / total;
        return new(macaulay, macaulay / growth, curvature / (total * growth * growth), (Dirty(rate - 0.0001) - Dirty(rate + 0.0001)) / 2);
    }
}
static class Schedule
{
    public static List<int> Build(int issue, int maturity, int frequency, bool eom, bool longStub)
    {
        DateOnly anchor = Dates.Civil(maturity); bool endMonth = eom && anchor.Day == Dates.MonthLength(anchor.Year, anchor.Month);
        List<int> dates = []; int boundary = maturity;
        while (boundary > issue)
        {
            dates.Add(boundary); int index = anchor.Year * 12 + anchor.Month - 1 - 12 / frequency * dates.Count;
            int year = index / 12, month = index % 12 + 1, length = Dates.MonthLength(year, month);
            boundary = Dates.DayNumber(year, month, endMonth ? length : Math.Min(anchor.Day, length));
        }
        if (longStub && boundary != issue && dates.Count >= 2) dates.RemoveAt(dates.Count - 1);
        dates.Add(issue); dates.Reverse(); return dates;
    }
}
